var cam=UnityEngine.Camera.main;var oldp=cam.transform.position;var oldq=cam.transform.rotation;var result=new System.Text.StringBuilder();
try{foreach(float pitch in new[]{5f,-5f,-10f,-15f,-25f}){cam.transform.SetPositionAndRotation(new UnityEngine.Vector3(58.37f,.59f,11.63f),UnityEngine.Quaternion.Euler(pitch,0,0));var mirror=UnityEngine.Matrix4x4.identity;mirror.m11=-1;mirror.m13=-.56f;var view=cam.worldToCameraMatrix*mirror;var point=view.MultiplyPoint(new UnityEngine.Vector3(0,-.265f,0));var normal=view.MultiplyVector(UnityEngine.Vector3.up).normalized;var plane=new UnityEngine.Vector4(normal.x,normal.y,normal.z,-UnityEngine.Vector3.Dot(point,normal));var oblique=cam.CalculateObliqueMatrix(plane);var projected=oblique*view*new UnityEngine.Vector4(58,5,36,1);var bottom=oblique*view*new UnityEngine.Vector4(58,-3.4f,25,1);result.AppendLine(pitch+" wallNDC="+(projected/projected.w)+" bottomNDC="+(bottom/bottom.w)+" plane="+plane);}}
finally{cam.transform.SetPositionAndRotation(oldp,oldq);}
return result.ToString();
